        длительность_запуска = (длительность_по_наблюдателю if длительность_по_наблюдателю is not None
                                 else max(0, конец - начало))
        план: list[dict[str, str]] | None = None
        наблюдения: list[dict[str, object]] = []
        текущая_проверка: dict[str, object] | None = None
